// Generate the downloadable install from the maintained source Compose definition.
// No registry, network, build or publication operation.
import { copyFileSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";

const root = fileURLToPath(new URL("..", import.meta.url));
export function bundleCompose(source) {
  return (
    "# Generated by scripts/release-bundle.mjs. Published images only.\n" +
    source
      .replace(/^# Core stack:[\s\S]*?(?=name:)/, "")
      .replace(/^ {4}build:.*\r?\n/gm, "")
      .replace(
        / {4}image: filecanopy-(\w+):dev/g,
        (_, service) =>
          `    pull_policy: missing\n    image: \${FILECANOPY_IMAGE_PREFIX:-ghcr.io/aulteran/filecanopy}-${service}:\${FILECANOPY_VERSION:?set FILECANOPY_VERSION to the explicit release version}`,
      )
      .replaceAll("in deploy/.env", "in .env")
      .replaceAll("../library", "./library")
      .replaceAll("../app-data", "./app-data")
  );
}

export function writeBundle(output) {
  // Refuse to mix an install, secrets or stale artifacts into a new bundle.
  mkdirSync(output);
  writeFileSync(
    join(output, "compose.yaml"),
    bundleCompose(
      readFileSync(join(root, "deploy/docker-compose.yml"), "utf8"),
    ),
  );
  copyFileSync(
    join(root, "deploy/release.env.example"),
    join(output, ".env.example"),
  );
  copyFileSync(
    join(root, "docs/guides/docker-install.md"),
    join(output, "INSTALL.md"),
  );
  mkdirSync(join(output, "scripts"));
  for (const name of ["backup.sh", "restore.sh", "lib.sh"])
    copyFileSync(
      join(root, "deploy/scripts", name),
      join(output, "scripts", name),
    );
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  if (process.argv.length !== 3)
    throw new Error(
      "Usage: node scripts/release-bundle.mjs NEW_OUTPUT_DIRECTORY",
    );
  writeBundle(process.argv[2]);
}
